struct Message: Sendable { let id: UUID; let text: String }   // value type

final class Config: Sendable { let baseURL: URL; init(_ u: URL) { baseURL = u } }  // immutable

import Synchronization
final class Counter: Sendable {                                 // protected state
    private let value = Mutex(0)
    func increment() -> Int { value.withLock { $0 += 1; return $0 } }
}
